"""Test harness: run the service over a trace and check the replies."""
import json
import subprocess
import sys

SERVICE = ['python3', '-I', '-B', '/workspace/submission/main.py']


def run(requests, raw=None):
    lines = []
    if raw is not None:
        lines = raw
    else:
        for r in requests:
            lines.append(json.dumps(r, separators=(',', ':')))
    data = ('\n'.join(lines) + '\n').encode('utf-8')
    proc = subprocess.run(SERVICE, input=data, stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE, timeout=120)
    if proc.stderr:
        sys.stderr.write(proc.stderr.decode('utf-8', 'replace'))
    out = proc.stdout.decode('utf-8').splitlines()
    return [json.loads(x) for x in out]


# ---------------------------------------------------------------------------
# independent plan checker (written from the protocol text)
# ---------------------------------------------------------------------------

def check_plan(plan, n, links, caps, participants, demands, period, offer):
    """Return (ok, reason).  ``caps`` maps link -> per period capacity p*b_l."""
    part = set(participants)
    D = sum(demands.values())
    if set(plan.keys()) != {'trees', 'routes', 'recipes'}:
        return False, 'plan keys'
    trees, routes, recipes = plan['trees'], plan['routes'], plan['recipes']
    if len(trees) > 8192 or len(routes) > 32768 or len(recipes) > 65536:
        return False, 'plan size'

    # recipe circuit: acyclic, well typed, walks
    memo = {}

    def walk(nid, stack):
        if nid in stack:
            raise ValueError('cycle')
        if nid in memo:
            return memo[nid]
        if not isinstance(nid, int) or isinstance(nid, bool):
            raise ValueError('bad ref')
        if nid < 0 or nid >= len(recipes):
            raise ValueError('ref range')
        node = recipes[nid]
        if not isinstance(node, list):
            raise ValueError('node type')
        if node[0] == 0:
            if len(node) != 3:
                raise ValueError('leaf arity')
            link, direction = node[1], node[2]
            if not isinstance(link, int) or isinstance(link, bool):
                raise ValueError('leaf link')
            if not isinstance(direction, int) or isinstance(direction, bool):
                raise ValueError('leaf dir')
            if link < 0 or link >= len(links) or direction not in (0, 1):
                raise ValueError('leaf range')
            u, v = links[link]
            memo[nid] = (u, v) if direction == 0 else (v, u)
            return memo[nid]
        if node[0] == 1:
            if len(node) != 3:
                raise ValueError('concat arity')
            l = walk(node[1], stack | {nid})
            r = walk(node[2], stack | {nid})
            if l[1] != r[0]:
                raise ValueError('concat mismatch')
            if l[1] in part:
                raise ValueError('concat at participant')
            memo[nid] = (l[0], r[1])
            return memo[nid]
        raise ValueError('node kind')

    for i in range(len(recipes)):
        try:
            walk(i, frozenset())
        except ValueError as exc:
            return False, 'recipe %s' % exc

    def leaves(nid):
        node = recipes[nid]
        if node[0] == 0:
            return [(node[1], node[2])]
        return leaves(node[1]) + leaves(node[2])

    weight = {}
    logical = {}
    for rec in trees:
        if not isinstance(rec, list) or len(rec) != 3:
            return False, 'tree shape'
        root, count, edges = rec
        if not isinstance(count, int) or isinstance(count, bool):
            return False, 'count type'
        if count <= 0 or count > D:
            return False, 'count range'
        if root not in part:
            return False, 'root'
        if len(edges) != len(part) - 1:
            return False, 'edge count'
        indeg = {}
        adj = {}
        for edge in edges:
            if not isinstance(edge, list) or len(edge) != 2:
                return False, 'edge shape'
            u, v = edge
            if u not in part or v not in part or u == v:
                return False, 'edge endpoints'
            if (u, v) in logical and False:
                pass
            key = (u, v)
            if key in seen_edges:
                return False, 'duplicate edge'
            seen_edges.add(key)
            indeg[v] = indeg.get(v, 0) + 1
            adj.setdefault(u, []).append(v)
        if indeg.get(root, 0) != 0:
            return False, 'root indegree'
        for node in part:
            if node != root and indeg.get(node, 0) != 1:
                return False, 'indegree'
        stack, seen = [root], {root}
        while stack:
            x = stack.pop()
            for y in adj.get(x, ()):
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        if seen != part:
            return False, 'reachability'
        weight[root] = weight.get(root, 0) + count
        for edge in edges:
            logical[(edge[0], edge[1])] = logical.get((edge[0], edge[1]), 0) + count

    for node in part:
        if demands[node] == 0:
            if weight.get(node, 0) != 0:
                return False, 'zero demand root has a tree'
        elif weight.get(node, 0) != demands[node]:
            return False, 'root weight'

    routed = {}
    load = {}
    for rec in routes:
        if not isinstance(rec, list) or len(rec) != 4:
            return False, 'route shape'
        u, v, count, recipe = rec
        if u not in part or v not in part or u == v:
            return False, 'route endpoints'
        if not isinstance(count, int) or isinstance(count, bool):
            return False, 'route count type'
        if count <= 0 or count > D:
            return False, 'route count range'
        if not isinstance(recipe, int) or isinstance(recipe, bool):
            return False, 'recipe ref'
        if recipe < 0 or recipe >= len(recipes):
            return False, 'recipe range'
        if memo[recipe] != (u, v):
            return False, 'recipe endpoints'
        routed[(u, v)] = routed.get((u, v), 0) + count
        for link, direction in leaves(recipe):
            load[(link, direction)] = load.get((link, direction), 0) + count
    for key, value in logical.items():
        if routed.get(key, 0) != value:
            return False, 'route sum for %s' % (key,)
    for key, value in routed.items():
        if logical.get(key, 0) != value:
            return False, 'extra route %s' % (key,)
    for (link, direction), value in load.items():
        if value > caps.get(link, 0):
            return False, 'load %s %s = %s > %s' % (link, direction, value, caps.get(link, 0))
    return True, 'ok'


